using System;
using System.Configuration;
using System.Net;
using System.Security.Authentication;
using System.Threading;
using System.Threading.Tasks;

using MailKit.Net.Smtp;
using MailKit.Security;
using MimeKit;

using Microsoft.Identity.Client;

namespace ALHMobileAppAPI.CommonUtilities
{
    public static class EmailHelper
    {
        // =========================================================
        // Configuration
        // =========================================================
        public const string LogoBase64Data =
            "";

        private static string Cfg(string key)
        {
            return ConfigurationManager.AppSettings[key];
        }

        // =========================================================
        // Force TLS 1.2 for every outbound HTTPS call this class makes
        // (MSAL's internal HttpClient, used by AcquireTokenForClient
        // below to reach login.microsoftonline.com).
        //
        // WHY THIS IS HERE: MailKit's client.SslProtocols = Tls12
        // further down only governs the SMTP connection itself. MSAL's
        // token request is a separate outbound HTTPS call that goes
        // through .NET Framework's ServicePointManager, which is NOT
        // covered by that setting. On a dev machine, Windows' default
        // enabled TLS versions for .NET Framework usually already
        // include 1.2, so this never gets exercised locally -- but a
        // number of Windows Server builds (2012 R2 in particular)
        // ship with ServicePointManager still defaulting to
        // SSL3/TLS 1.0 unless a .NET 4.6+ app explicitly opts in. If
        // that's the server's actual OS, GetAccessTokenAsync below
        // fails with a TLS handshake / "could not create SSL/TLS
        // secure channel" error the moment it hits a real server,
        // while working every time from a dev box that already
        // allows TLS 1.2. A static constructor runs once, before any
        // other static member on this class (including the Lazy
        // MsalApp below) is first touched, so this is guaranteed to
        // run before the first token request.
        // =========================================================
        static EmailHelper()
        {
            ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;
        }

        // =========================================================
        // Inline logo
        //
        // Content-Id referenced by the branded email templates as
        // <img src="cid:ahhlogo" .../> (see SignatureService.cs and
        // EsignService.cs BuildEmailBody). Email clients cannot
        // reach a Windows file path directly, so the logo is
        // attached to every outgoing message as an inline (CID)
        // resource instead of linked by URL.
        //
        // The logo is now baked in as a BASE64 STRING CONSTANT
        // (see EmailLogoResource.cs, LogoBase64Data) rather than read
        // from either a file path or an embedded assembly resource.
        // Both of the earlier approaches turned out to be environment-
        // dependent in their own way: the file-path version broke
        // because D:\GIT\ZOHOAPI\... didn't exist on the real server,
        // and the embedded-resource version broke because its actual
        // manifest resource name (ALHMobileAppAPI.Images.AHH-Logo.png)
        // didn't match what the code assumed (depends on which project
        // folder the file sits in + its Build Action being set to
        // "Embedded Resource" correctly at build time). A base64
        // string compiled directly into the DLL has neither failure
        // mode -- there's no file path and no resource name to get
        // wrong, so it can't silently break again after a deploy.
        //
        // The bytes are still attached as an inline CID resource (not
        // a data: URI in the HTML) via MimeKit's
        // LinkedResources.Add(fileName, byte[]) -- see below -- because
        // Outlook desktop's renderer does not reliably display
        // data: URI images in HTML email, while cid: attachments work
        // everywhere.
        // =========================================================

        public const string LogoContentId = "ahhlogo";

        // =========================================================
        // MSAL Application
        //
        // IMPORTANT:
        // This is intentionally created only once.
        // MSAL maintains its token cache internally.
        // =========================================================

        private static readonly Lazy<IConfidentialClientApplication> MsalApp =
            new Lazy<IConfidentialClientApplication>(() =>
            {
                string clientId = Cfg("AzureAd.ClientId");
                string clientSecret = Cfg("AzureAd.ClientSecret");
                string tenantId = Cfg("AzureAd.TenantId");

                if (string.IsNullOrWhiteSpace(clientId))
                    throw new ConfigurationErrorsException(
                        "AzureAd.ClientId is missing.");

                if (string.IsNullOrWhiteSpace(clientSecret))
                    throw new ConfigurationErrorsException(
                        "AzureAd.ClientSecret is missing.");

                if (string.IsNullOrWhiteSpace(tenantId))
                    throw new ConfigurationErrorsException(
                        "AzureAd.TenantId is missing.");

                return ConfidentialClientApplicationBuilder
                    .Create(clientId)
                    .WithClientSecret(clientSecret)
                    .WithAuthority(
                        "https://login.microsoftonline.com/" + tenantId)
                    .Build();
            });

        // =========================================================
        // Get OAuth token
        // =========================================================

        private static async Task<string> GetAccessTokenAsync(
            CancellationToken cancellationToken)
        {
            var result = await MsalApp.Value
                .AcquireTokenForClient(
                    new[]
                    {
                        "https://outlook.office365.com/.default"
                    })
                .ExecuteAsync(cancellationToken)
                .ConfigureAwait(false);

            if (result == null ||
                string.IsNullOrWhiteSpace(result.AccessToken))
            {
                throw new InvalidOperationException(
                    "Microsoft Entra ID returned an empty access token.");
            }

            return result.AccessToken;
        }

        // =========================================================
        // Public async method
        // =========================================================

        public static async Task<bool> SendEmailAsync(
            string toEmail,
            string toName,
            string subject,
            string htmlBody,
            CancellationToken cancellationToken = default(CancellationToken))
        {
            if (string.IsNullOrWhiteSpace(toEmail))
                return false;

            // -----------------------------------------------------
            // Configuration
            // -----------------------------------------------------

            string host =
                Cfg("Smtp.Host") ??
                "smtp.office365.com";

            int port =
                int.TryParse(
                    Cfg("Smtp.Port"),
                    out int configuredPort)
                    ? configuredPort
                    : 587;

            string fromName =
                Cfg("Smtp.FromName") ??
                "Al Hammadi e-Signature";

            string fromAddress =
                Cfg("Smtp.FromAddress");

            if (string.IsNullOrWhiteSpace(fromAddress))
            {
                throw new ConfigurationErrorsException(
                    "Smtp.FromAddress is missing.");
            }

            // -----------------------------------------------------
            // Create message
            // -----------------------------------------------------

            var message = new MimeMessage();

            message.From.Add(
                new MailboxAddress(
                    fromName,
                    fromAddress));

            message.To.Add(
                new MailboxAddress(
                    string.IsNullOrWhiteSpace(toName)
                        ? toEmail
                        : toName,
                    toEmail));

            message.Subject = subject;

            var bodyBuilder = new BodyBuilder
            {
                HtmlBody = htmlBody
            };

            // -----------------------------------------------------
            // Inline logo attachment (best-effort -- a malformed or
            // empty base64 constant must never block the email from
            // sending; the template's <img> just renders broken/shows
            // its alt text in that case).
            // -----------------------------------------------------

            try
            {
                if (!string.IsNullOrWhiteSpace(LogoBase64Data))
                {
                    byte[] logoBytes = Convert.FromBase64String(LogoBase64Data);

                    // MimeKit's LinkedResources.Add(name, byte[]) overload --
                    // no stream/file/assembly-resource involved at all.
                    var logo = bodyBuilder.LinkedResources.Add("AHH-Logo.png", logoBytes);
                    logo.ContentId = LogoContentId;
                }
                else
                {
                    HIS.TOOLS.Logger.ErrorLog.ErrorRoutine(
                        new InvalidOperationException(
                            "EmailLogoResource.LogoBase64Data is empty -- paste the logo's base64 string in EmailLogoResource.cs."),
                        "EmailHelper", "Could not attach inline logo", "");
                }
            }
            catch (Exception ex)
            {
                HIS.TOOLS.Logger.ErrorLog.ErrorRoutine(
                    ex,
                    "EmailHelper",
                    "Could not attach inline logo",
                    "");
            }

            message.Body = bodyBuilder.ToMessageBody();

            // -----------------------------------------------------
            // Get OAuth token
            // -----------------------------------------------------

            string accessToken;
            try
            {
                accessToken =
                    await GetAccessTokenAsync(cancellationToken)
                        .ConfigureAwait(false);
            }
            catch (Exception ex)
            {
                HIS.TOOLS.Logger.ErrorLog.ErrorRoutine(
                    ex, "EmailHelper",
                    "STAGE=TokenAcquisition (MSAL AcquireTokenForClient -> login.microsoftonline.com). " +
                    "Check AzureAd.ClientId/ClientSecret/TenantId, the app registration's Mail.Send/SMTP.Send grant, " +
                    "and whether the server can reach login.microsoftonline.com:443.",
                    toEmail);
                throw;
            }

            cancellationToken.ThrowIfCancellationRequested();

            // -----------------------------------------------------
            // SMTP
            // -----------------------------------------------------

            using (var client = new SmtpClient())
            {
                // 30 second MailKit timeout
                client.Timeout = 30000;

                // TLS 1.2
                client.SslProtocols =
                    SslProtocols.Tls12;

                // -------------------------------------------------
                // Connect
                // -------------------------------------------------

                try
                {
                    await client
                        .ConnectAsync(
                            host,
                            port,
                            SecureSocketOptions.StartTls,
                            cancellationToken)
                        .ConfigureAwait(false);
                }
                catch (Exception ex)
                {
                    HIS.TOOLS.Logger.ErrorLog.ErrorRoutine(
                        ex, "EmailHelper",
                        $"STAGE=SmtpConnect (host={host}, port={port}). " +
                        "Check the server can reach this host/port outbound (firewall/NSG) -- " +
                        "e.g. Test-NetConnection " + host + " -Port " + port + " run ON THE SERVER.",
                        toEmail);
                    throw;
                }

                cancellationToken.ThrowIfCancellationRequested();

                // -------------------------------------------------
                // OAuth2 / XOAUTH2
                // -------------------------------------------------

                var oauth2 =
                    new SaslMechanismOAuth2(
                        fromAddress,
                        accessToken);

                try
                {
                    await client
                        .AuthenticateAsync(
                            oauth2,
                            cancellationToken)
                        .ConfigureAwait(false);
                }
                catch (Exception ex)
                {
                    HIS.TOOLS.Logger.ErrorLog.ErrorRoutine(
                        ex, "EmailHelper",
                        $"STAGE=SmtpAuthenticate (XOAUTH2, fromAddress={fromAddress}). " +
                        "Token was acquired fine (TokenAcquisition stage passed), so this usually means the " +
                        "mailbox itself isn't SMTP-AUTH/app-only-send enabled in Exchange Online, or the token's " +
                        "audience/scope doesn't match what this mailbox accepts.",
                        toEmail);
                    throw;
                }

                cancellationToken.ThrowIfCancellationRequested();

                // -------------------------------------------------
                // Send
                // -------------------------------------------------

                try
                {
                    await client
                        .SendAsync(
                            message,
                            cancellationToken)
                        .ConfigureAwait(false);
                }
                catch (Exception ex)
                {
                    HIS.TOOLS.Logger.ErrorLog.ErrorRoutine(
                        ex, "EmailHelper",
                        "STAGE=SmtpSend. Connected and authenticated fine -- this is a failure from the SMTP " +
                        "server on the SendAsync call itself (e.g. rejected sender/recipient, size limit, throttling).",
                        toEmail);
                    throw;
                }

                // -------------------------------------------------
                // Disconnect (best-effort -- the email above already
                // sent successfully at this point, so a disconnect
                // failure must not turn a successful send into a
                // reported failure; log and swallow instead of
                // rethrowing).
                // -------------------------------------------------

                if (client.IsConnected)
                {
                    try
                    {
                        await client
                            .DisconnectAsync(
                                true,
                                cancellationToken)
                            .ConfigureAwait(false);
                    }
                    catch (Exception ex)
                    {
                        HIS.TOOLS.Logger.ErrorLog.ErrorRoutine(
                            ex, "EmailHelper",
                            "STAGE=SmtpDisconnect (non-fatal -- message already sent successfully).",
                            toEmail);
                    }
                }
            }

            return true;
        }
    }
}